import { readdirSync, readFileSync } from "node:fs";
import { join, resolve } from "node:path";

/**
 * Test-only access to the in-repo golden ProtoJSON fixtures
 * (`proto/rasa/events/v1/fixtures`). Parsing itself goes through
 * `@rasahq/rasa-events`.
 */

const CONTRACT_DIR = resolve(__dirname, "../../../../../../proto/rasa/events/v1");

export type GoldenFixture = {
  name: string;
  envelope: Record<string, unknown>;
};

export function loadGoldenFixtures(): GoldenFixture[] {
  const fixturesDir = join(CONTRACT_DIR, "fixtures");
  return readdirSync(fixturesDir)
    .filter((fileName) => fileName.endsWith(".json"))
    .sort()
    .map((fileName) => ({
      name: fileName.replace(/\.json$/, ""),
      envelope: JSON.parse(readFileSync(join(fixturesDir, fileName), "utf8")) as Record<
        string,
        unknown
      >,
    }));
}
